PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY, recovery_hash TEXT UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, actor TEXT NOT NULL, role TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY, kind TEXT NOT NULL, owner TEXT NOT NULL, code TEXT UNIQUE NOT NULL, version INTEGER NOT NULL DEFAULT 1, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT, record_id TEXT NOT NULL, actor TEXT NOT NULL, type TEXT NOT NULL, reason TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY AUTOINCREMENT, journal TEXT NOT NULL, record_id TEXT NOT NULL, account TEXT NOT NULL, amount INTEGER NOT NULL, created INTEGER NOT NULL, UNIQUE(journal,account));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, record_id TEXT NOT NULL, type TEXT NOT NULL, state TEXT NOT NULL, due INTEGER NOT NULL, scenario TEXT NOT NULL, reference TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS callbacks(event_id TEXT PRIMARY KEY, receipt_id TEXT UNIQUE NOT NULL, record_id TEXT NOT NULL, amount INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS commands(actor TEXT NOT NULL, key TEXT NOT NULL, body_hash TEXT NOT NULL, result TEXT NOT NULL, PRIMARY KEY(actor,key));
CREATE TABLE IF NOT EXISTS proposals(id TEXT PRIMARY KEY, record_id TEXT NOT NULL, proposer TEXT NOT NULL, approver TEXT, action TEXT NOT NULL, reason TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL, amount INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS evidence(id TEXT PRIMARY KEY, record_id TEXT NOT NULL, actor TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, content BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS no_event_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'Events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS no_event_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'Events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS no_ledger_update BEFORE UPDATE ON ledger BEGIN SELECT RAISE(ABORT,'Ledger is append-only'); END;
CREATE TRIGGER IF NOT EXISTS no_ledger_delete BEFORE DELETE ON ledger BEGIN SELECT RAISE(ABORT,'Ledger is append-only'); END;
